-- 미시경제 레슨 1: 317 수요탄력성, 52 공급탄력성, 783 대체재, 241 보완재, 795 소비자잉여, 797 사중손실, 806 최고가격제, 825 조세 귀착, 643 한계비용, 645 한계효용, 810 생산가능곡선, 803 무차별곡선, 324 수확체감의 법칙, 94 규모의 경제
-- 근거: 테셋05~36 블로그 글(탄력성·잉여·조세·한계·생산가능곡선·무차별곡선·생산·비용·시장구조·지대·분배·후생·시장실패·정보 비대칭).
-- 카드(text/table/flow)와 퀴즈 2개(그중 lessonCheck 1개)를 기존 visuals 앞에 붙인다. 첫 카드 제목이 이미 있으면 건너뜀(다시 실행해도 중복 없음).

-- 수요탄력성 (317)
UPDATE public.words SET visuals = '[
  {"type": "text", "title": "수요탄력성 쉽게 설명", "body": "값이 1% 변할 때 사려는 양이 몇 % 변하는지 재는 숫자예요.\n변화량이 아니라 변화율로 재고, 가격과 수요량은 반대로 움직여서 절댓값으로 크기만 봐요.\n1보다 크면 탄력적, 1보다 작으면 비탄력적이에요."},
  {"type": "table", "title": "탄력성과 매출(총수입)", "columns": ["구분", "값을 올리면", "값을 내리면"], "rows": [["탄력적 (1 초과)", "매출 감소", "매출 증가"], ["단위 탄력적 (1)", "변화 없음", "변화 없음"], ["비탄력적 (1 미만)", "매출 증가", "매출 감소"]], "caption": "매출은 가격 × 판매량이라, 둘 중 어느 쪽이 더 크게 움직이느냐를 탄력성이 정해요."},
  {"type": "text", "title": "탄력성을 키우는 것들", "body": "대신할 물건이 많을수록, 지출에서 차지하는 몫이 클수록, 필수품보다 사치품일수록 탄력적이에요.\n시간이 길수록, 상품 범위를 좁게 잡을수록(술 전체보다 특정 브랜드 소주) 탄력적이에요."},
  {"type": "quiz", "q": "어떤 과자 값이 10% 오르자 판매량이 25% 줄었어요. 이 과자 수요에 대한 설명으로 옳은 것은?", "options": ["탄력적이고, 값을 올리면 매출이 줄어요", "비탄력적이고, 값을 올리면 매출이 늘어요", "단위 탄력적이라 매출이 그대로예요", "완전 비탄력적이에요"], "answer": 0, "explanation": "탄력성은 25% ÷ 10% = 2.5로 1보다 커요. 판매량이 가격보다 더 크게 줄어서 값을 올리면 매출이 줄어요.", "lessonCheck": true},
  {"type": "quiz", "q": "쌀처럼 값이 바뀌어도 먹는 양이 크게 안 바뀌는 상품의 수요는?", "options": ["비탄력적", "탄력적", "완전 탄력적", "단위 탄력적"], "answer": 0, "explanation": "가격이 변해도 수요량이 덜 변하면 비탄력적이에요. 필수품이고 대신할 것이 적을수록 비탄력적이 돼요."}
]'::jsonb || COALESCE(visuals,'[]'::jsonb)
WHERE id = 317 AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"title": "수요탄력성 쉽게 설명"}]'::jsonb;

-- 공급탄력성 (52)
UPDATE public.words SET visuals = '[
  {"type": "text", "title": "공급탄력성 쉽게 설명", "body": "값이 1% 오를 때 팔려는 양이 몇 % 늘어나는지 재는 숫자예요.\n공급량은 가격과 같은 방향으로 움직여서 보통 양수로 나와요.\n공급곡선이 누워 있을수록 탄력적, 서 있을수록 비탄력적이에요."},
  {"type": "table", "title": "공급이 비탄력적이 되는 경우", "columns": ["요인", "비탄력적인 쪽", "예"], "rows": [["양 자체가 고정", "늘릴 수 없음", "토지, 골동품"], ["생산에 걸리는 시간", "길수록", "농산물(공산품보다)"], ["생산을 늘릴 때 비용", "크게 오를수록", "재료 구하기 어려운 상품"], ["저장", "어려울수록", "쉽게 상하는 상품"]], "caption": "시간이 지나 설비를 늘릴 수 있게 되면 공급은 더 탄력적이 돼요."},
  {"type": "text", "title": "공급이 극단일 때 수요가 늘면", "body": "공급곡선이 수평(완전 탄력적)이면 가격은 그대로, 거래량만 늘어요.\n공급곡선이 수직(완전 비탄력적)이면 거래량은 그대로, 가격만 올라요.\n농산물은 수요와 공급이 모두 비탄력적이라 작은 변화에도 값이 크게 출렁여요."},
  {"type": "quiz", "q": "양을 전혀 늘릴 수 없는 골동품을 사려는 사람이 늘었어요. 어떻게 될까요?", "options": ["가격만 오르고 거래량은 그대로예요", "거래량만 늘고 가격은 그대로예요", "가격과 거래량이 모두 줄어요", "가격은 내리고 거래량은 늘어요"], "answer": 0, "explanation": "공급이 완전 비탄력적이면 공급곡선이 수직이에요. 수요가 늘어도 양을 못 늘리니 가격만 올라요.", "lessonCheck": true},
  {"type": "quiz", "q": "공급이 더 비탄력적이 되는 경우는?", "options": ["생산하는 데 시간이 오래 걸릴 때", "저장이 쉬울 때", "생산을 늘려도 비용이 거의 안 오를 때", "공장 설비를 쉽게 늘릴 수 있을 때"], "answer": 0, "explanation": "가격이 올라도 금방 더 만들 수 없으면 공급량이 덜 늘어나요. 생산 기간이 길수록 공급은 비탄력적이에요."}
]'::jsonb || COALESCE(visuals,'[]'::jsonb)
WHERE id = 52 AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"title": "공급탄력성 쉽게 설명"}]'::jsonb;

-- 대체재 (783)
UPDATE public.words SET visuals = '[
  {"type": "text", "title": "대체재 쉽게 설명", "body": "콜라와 사이다처럼 서로 대신 쓸 수 있는 상품이에요.\n사이다 값이 오르면 콜라를 대신 찾으니 콜라 수요가 늘어요.\n상대 상품의 값과 내 상품의 수요가 같은 방향으로 움직여요."},
  {"type": "table", "title": "대체재 vs 보완재", "columns": ["구분", "대체재", "보완재"], "rows": [["뜻", "서로 대신 쓰는 상품", "함께 쓰는 상품"], ["예", "콜라와 사이다", "햄버거와 콜라"], ["상대 값이 오르면", "내 상품 수요 증가", "내 상품 수요 감소"], ["교차탄력성", "양수(+)", "음수(-)"]], "caption": "다른 상품 값이 바뀌면 내 상품의 수요곡선 자체가 움직여요."},
  {"type": "quiz", "q": "버터 값이 크게 오르자 마가린을 사려는 사람이 늘었어요. 두 상품의 관계와 마가린 수요곡선의 변화는?", "options": ["대체재, 마가린 수요곡선이 오른쪽으로 이동", "보완재, 마가린 수요곡선이 왼쪽으로 이동", "대체재, 마가린 수요곡선 위에서 점만 이동", "관계없는 상품, 변화 없음"], "answer": 0, "explanation": "버터와 마가린은 서로 대신 쓰는 대체재예요. 다른 상품 값이 바뀌어 같은 가격에서도 더 사니 마가린 수요곡선 자체가 오른쪽으로 움직여요.", "lessonCheck": true},
  {"type": "quiz", "q": "두 상품의 교차탄력성이 양수(+)예요. 두 상품은?", "options": ["대체재", "보완재", "열등재", "기펜재"], "answer": 0, "explanation": "한 상품 값이 오를 때 다른 상품 수요가 늘면 교차탄력성이 양수예요. 서로 대신 쓰는 대체재의 특징이에요."}
]'::jsonb || COALESCE(visuals,'[]'::jsonb)
WHERE id = 783 AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"title": "대체재 쉽게 설명"}]'::jsonb;

-- 보완재 (241)
UPDATE public.words SET visuals = '[
  {"type": "text", "title": "보완재 쉽게 설명", "body": "햄버거와 콜라, 짜장면과 단무지처럼 함께 쓸 때 만족이 커지는 상품이에요.\n콜라 값이 오르면 세트로 먹는 부담이 커져 햄버거 수요가 줄어요.\n상대 상품의 값과 내 상품의 수요가 반대 방향으로 움직여요."},
  {"type": "table", "title": "햄버거 수요는 어떻게 움직일까", "columns": ["바뀐 것", "햄버거 수요", "수요곡선"], "rows": [["샌드위치(대체재) 값 하락", "감소", "왼쪽 이동"], ["샌드위치(대체재) 값 상승", "증가", "오른쪽 이동"], ["콜라(보완재) 값 하락", "증가", "오른쪽 이동"], ["콜라(보완재) 값 상승", "감소", "왼쪽 이동"]], "caption": "햄버거 자기 값이 바뀔 때는 곡선은 그대로이고 곡선 위에서 점만 움직여요."},
  {"type": "quiz", "q": "프린터 잉크 값이 크게 올랐어요. 프린터 수요는 어떻게 될까요?", "options": ["줄어서 수요곡선이 왼쪽으로 이동해요", "늘어서 수요곡선이 오른쪽으로 이동해요", "프린터 값이 그대로라 전혀 변하지 않아요", "수요곡선 위에서 점만 움직여요"], "answer": 0, "explanation": "프린터와 잉크는 함께 쓰는 보완재예요. 잉크 값이 오르면 프린터를 쓰는 부담이 커져 같은 가격에서도 덜 사니 수요곡선이 왼쪽으로 움직여요.", "lessonCheck": true},
  {"type": "quiz", "q": "교차탄력성이 음수(-)인 두 상품의 예로 알맞은 것은?", "options": ["자동차와 휘발유", "콜라와 사이다", "버터와 마가린", "버스와 지하철"], "answer": 0, "explanation": "한쪽 값이 오를 때 다른 쪽 수요가 줄면 교차탄력성이 음수예요. 함께 쓰는 자동차와 휘발유 같은 보완재가 그래요."}
]'::jsonb || COALESCE(visuals,'[]'::jsonb)
WHERE id = 241 AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"title": "보완재 쉽게 설명"}]'::jsonb;

-- 소비자잉여 (795)
UPDATE public.words SET visuals = '[
  {"type": "text", "title": "소비자잉여 쉽게 설명", "body": "낼 생각이 있던 최대 금액(최대 지불 의사)에서 실제로 낸 가격을 뺀 만큼이에요.\n운동 뒤 첫 콜라에 5,000원도 낼 생각이었는데 1,000원에 샀다면 4,000원만큼 이득이에요.\n그래프에서는 가격선 위, 수요곡선 아래 삼각형이에요."},
  {"type": "table", "title": "소비자잉여 vs 생산자잉여", "columns": ["구분", "소비자잉여", "생산자잉여"], "rows": [["계산", "최대 지불 의사 - 가격", "가격 - 최소로 받으려던 금액"], ["그래프", "가격선 위·수요곡선 아래", "가격선 아래·공급곡선 위"], ["곡선 모양의 이유", "한계효용 체감", "한계비용 체증"]], "caption": "두 잉여를 더한 것이 사회후생이고, 수요와 공급이 만나는 균형에서 가장 커요."},
  {"type": "quiz", "q": "콘서트 표에 15만 원까지 낼 생각이었는데 9만 원에 샀어요. 이 사람의 소비자잉여는?", "options": ["6만 원", "9만 원", "15만 원", "24만 원"], "answer": 0, "explanation": "소비자잉여는 최대 지불 의사에서 실제 가격을 뺀 값이에요. 15만 원 - 9만 원 = 6만 원이에요.", "lessonCheck": true},
  {"type": "quiz", "q": "다른 조건은 같은데 공급이 줄어 시장 가격이 올랐어요. 소비자잉여는?", "options": ["줄어요", "늘어요", "변하지 않아요", "반드시 0이 돼요"], "answer": 0, "explanation": "가격이 오르면 사던 사람은 더 비싸게 사고, 일부는 아예 못 사요. 그래서 소비자잉여가 줄어요."}
]'::jsonb || COALESCE(visuals,'[]'::jsonb)
WHERE id = 795 AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"title": "소비자잉여 쉽게 설명"}]'::jsonb;

-- 사중손실 (797)
UPDATE public.words SET visuals = '[
  {"type": "text", "title": "사중손실 쉽게 설명", "body": "가격 규제나 세금 때문에 거래량이 균형보다 줄면서 누구에게도 돌아가지 않고 사라진 잉여예요.\n더 거래됐다면 사는 쪽과 파는 쪽이 얻었을 이득이 없어진 거예요.\n그래프에서는 사라진 삼각형으로 나타나요."},
  {"type": "table", "title": "가격 상한으로 보는 사중손실", "columns": ["항목", "규제 전", "상한 40"], "rows": [["거래량", "40", "20"], ["소비자잉여", "800", "1,000"], ["생산자잉여", "800", "200"], ["사회후생", "1,600", "1,200"]], "caption": "수요 P = 100 - Q, 공급 P = 20 + Q인 시장이에요. 사회후생이 줄어든 400이 사중손실이에요."},
  {"type": "text", "title": "사중손실이 커지는 경우", "body": "세금을 매겨도 거래량이 줄어 사중손실(초과부담)이 생겨요.\n수요나 공급이 탄력적일수록 거래량이 크게 줄어 사중손실도 커져요.\n그래서 효율만 보면 비탄력적인 상품에 매기는 세금이 손실이 적어요."},
  {"type": "quiz", "q": "정부가 어떤 상품에 개당 세금을 매겨 거래량이 줄었어요. 이때 생기는 사중손실에 대한 설명으로 옳은 것은?", "options": ["줄어든 거래에서 생겼을 잉여가 사라진 거예요", "정부가 걷은 세금 전체예요", "소비자가 더 낸 금액이에요", "생산자가 덜 받은 금액이에요"], "answer": 0, "explanation": "세금 수입은 정부에게 옮겨 간 돈이라 사라진 게 아니에요. 거래량이 줄어 아무에게도 돌아가지 않은 잉여가 사중손실이에요.", "lessonCheck": true},
  {"type": "quiz", "q": "같은 세금을 매길 때 사중손실이 더 커지는 상품은?", "options": ["수요가 탄력적인 상품", "수요가 완전 비탄력적인 상품", "공급이 완전 비탄력적인 상품", "대신할 상품이 거의 없는 상품"], "answer": 0, "explanation": "탄력적이면 세금에 반응해 거래량이 크게 줄어요. 줄어든 거래가 많을수록 사라지는 잉여도 커요."}
]'::jsonb || COALESCE(visuals,'[]'::jsonb)
WHERE id = 797 AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"title": "사중손실 쉽게 설명"}]'::jsonb;

-- 최고가격제 (806)
UPDATE public.words SET visuals = '[
  {"type": "text", "title": "최고가격제 쉽게 설명", "body": "정부가 가격이 일정 수준 위로 못 오르게 상한을 정하는 제도예요. 임대료 상한제가 대표적인 예예요.\n상한이 시장가격보다 낮아야 효과가 있어요. 시장가격보다 높게 정하면 원래 가격 그대로라 아무 변화가 없어요."},
  {"type": "table", "title": "최고가격제 vs 최저가격제", "columns": ["구분", "최고가격제", "최저가격제"], "rows": [["정하는 것", "가격 상한", "가격 하한"], ["효과가 있는 조건", "상한 < 시장가격", "하한 > 시장가격"], ["생기는 것", "초과수요(물건 부족)", "초과공급(물건·일손 남음)"], ["반드시 감소", "생산자잉여, 사회후생", "소비자잉여, 사회후생"], ["대표 사례", "임대료 상한제", "최저임금제"]]},
  {"type": "text", "title": "최고가격제가 낳는 일", "body": "싼값에 사려는 사람은 많은데 팔려는 양은 줄어 물건이 모자라요.\n싸게 산 사람은 이득이지만 못 사는 사람도 생겨서 소비자잉여는 늘 수도, 줄 수도 있어요.\n줄 서기, 암시장, 품질 저하가 생길 수 있어요."},
  {"type": "quiz", "q": "시장 임대료가 월 80만 원인 지역에 정부가 임대료 상한을 60만 원으로 정했어요. 교과서 모형에서 나타날 결과는?", "options": ["방을 구하려는 사람이 빌려주려는 방보다 많아져요", "빈방이 남아돌아요", "임대료가 80만 원 그대로 유지돼요", "사회 전체 후생이 늘어나요"], "answer": 0, "explanation": "상한이 시장가격보다 낮아 효과가 있어요. 싼값에 빌리려는 사람은 늘고 빌려주려는 방은 줄어 초과수요가 생겨요.", "lessonCheck": true},
  {"type": "quiz", "q": "최고가격제에서 반드시 줄어드는 것은?", "options": ["생산자잉여", "소비자잉여", "수요량", "초과수요"], "answer": 0, "explanation": "파는 쪽은 더 싸게, 더 적게 팔게 되어 생산자잉여가 반드시 줄어요. 소비자잉여는 늘 수도 줄 수도 있어요."}
]'::jsonb || COALESCE(visuals,'[]'::jsonb)
WHERE id = 806 AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"title": "최고가격제 쉽게 설명"}]'::jsonb;

-- 조세 귀착 (825)
UPDATE public.words SET visuals = '[
  {"type": "text", "title": "조세 귀착 쉽게 설명", "body": "세금을 매긴 사람과 실제로 세금을 떠안는 사람은 다를 수 있어요.\n세금을 남에게 넘기는 걸 전가, 넘겨받아 실제로 부담하는 걸 귀착이라고 해요.\n캔디 생산자에게 개당 30원을 매겼는데 값이 10원 올랐다면 소비자가 10원, 생산자가 20원을 부담한 셈이에요."},
  {"type": "table", "title": "실제 부담은 탄력성이 정해요", "columns": ["구분", "수요가 탄력적", "수요가 비탄력적"], "rows": [["소비자 상황", "다른 선택지가 많음", "다른 선택지가 적음"], ["값을 올리면", "바로 다른 곳으로 감", "그대로 살 수밖에 없음"], ["세금 부담", "생산자가 더 냄", "소비자가 더 냄"]], "caption": "덜 아쉬운 쪽, 즉 탄력성이 큰 쪽이 세금을 덜 내요."},
  {"type": "text", "title": "누구에게 매겨도 결과는 같아요", "body": "공급자에게 매기면 공급곡선이 세금만큼 위로, 소비자에게 매기면 수요곡선이 세금만큼 아래로 움직여요.\n가격표만 달라질 뿐, 소비자가 실제로 내는 돈과 생산자가 실제로 받는 돈은 똑같아요."},
  {"type": "quiz", "q": "옮겨 갈 비슷한 방이 거의 없고 방을 구하려는 사람이 줄을 서 있는 동네예요. 정부가 집주인에게 임대 소득세를 새로 매기면 세금 부담은?", "options": ["세입자가 더 많이 떠안을 가능성이 커요", "집주인에게 매겼으니 집주인이 전부 내요", "정부가 대신 부담해요", "누구도 부담하지 않아요"], "answer": 0, "explanation": "세입자 수요가 비탄력적이라 집주인이 월세를 올려도 세입자가 떠나기 어려워요. 탄력성이 작은 쪽이 세금을 더 많이 떠안아요.", "lessonCheck": true},
  {"type": "quiz", "q": "공급이 완전 비탄력적(수직)인 상품에 세금을 매기면 세금은 누가 부담할까요?", "options": ["생산자가 전부", "소비자가 전부", "반반씩", "정부"], "answer": 0, "explanation": "공급량이 전혀 변하지 않으니 가격을 올려 넘길 수 없어요. 그래서 생산자가 세금을 전부 떠안아요."}
]'::jsonb || COALESCE(visuals,'[]'::jsonb)
WHERE id = 825 AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"title": "조세 귀착 쉽게 설명"}]'::jsonb;

-- 한계비용 (643)
UPDATE public.words SET visuals = '[
  {"type": "text", "title": "한계비용 쉽게 설명", "body": "하나 더 만들 때 늘어나는 비용이에요. 총비용이 늘어난 만큼을 생산량이 늘어난 만큼으로 나눠 구해요.\n같은 설비로 계속 더 만들면 단기에는 한계비용이 점점 커지는데, 이를 한계비용 체증이라고 해요."},
  {"type": "table", "title": "빵으로 계산해 보기", "columns": ["빵", "총비용", "평균비용", "한계비용"], "rows": [["1개", "7원", "7원", "7원"], ["2개", "15원", "7.5원", "8원"], ["3개", "24원", "8원", "9원"]], "caption": "평균비용은 총비용 ÷ 개수, 한계비용은 하나 더 만들 때 늘어난 총비용이에요."},
  {"type": "text", "title": "한계비용이 평균을 끌고 다녀요", "body": "새 과목 점수가 평균보다 높으면 평균이 오르듯, 한계비용이 평균비용보다 크면 평균비용이 올라가요.\n한계비용이 평균비용보다 작으면 평균비용이 내려가요. 그래서 한계비용곡선은 평균비용의 가장 낮은 점을 지나요."},
  {"type": "quiz", "q": "빵을 10개 만들 때 총비용이 5만 원, 11개 만들 때 5만 6천 원이에요. 11번째 빵의 한계비용은?", "options": ["6천 원", "약 5천 원", "5만 6천 원", "5만 원"], "answer": 0, "explanation": "한계비용은 하나 더 만들 때 늘어난 총비용이에요. 5만 6천 원 - 5만 원 = 6천 원이에요.", "lessonCheck": true},
  {"type": "quiz", "q": "지금 한계비용이 평균비용보다 커요. 하나를 더 만들면 평균비용은?", "options": ["올라가요", "내려가요", "변하지 않아요", "0이 돼요"], "answer": 0, "explanation": "평균보다 비싼 하나가 더해지면 평균이 올라가요. 한계비용이 평균비용보다 크면 평균비용은 오르는 구간이에요."}
]'::jsonb || COALESCE(visuals,'[]'::jsonb)
WHERE id = 643 AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"title": "한계비용 쉽게 설명"}]'::jsonb;

-- 한계효용 (645)
UPDATE public.words SET visuals = '[
  {"type": "text", "title": "한계효용 쉽게 설명", "body": "같은 것을 하나 더 소비할 때 늘어나는 만족이에요.\n목마를 때 첫 콜라는 아주 시원하지만 둘째, 셋째로 갈수록 만족이 줄어요. 이것이 한계효용 체감이에요.\n그래서 더 살수록 내려는 값이 줄고, 수요곡선이 오른쪽 아래로 내려가요."},
  {"type": "table", "title": "한계효용 vs 총효용", "columns": ["콜라", "한계효용(하나 더)", "총효용(누적)"], "rows": [["1병째", "5,000원어치", "5,000원어치"], ["2병째", "2,000원어치", "7,000원어치"], ["3병째", "400원어치", "7,400원어치"]], "caption": "한계효용이 줄어도 0보다 크면 총효용은 계속 늘어요."},
  {"type": "text", "title": "1원당 한계효용을 맞춰요", "body": "돈을 나눠 쓸 때는 한계효용 자체가 아니라 가격으로 나눈 1원당 한계효용을 비교해요.\n1원당 한계효용이 큰 쪽을 더 사고, 모든 상품의 1원당 한계효용이 같아질 때 만족이 가장 커요. 이것이 한계효용 균등의 법칙이에요."},
  {"type": "quiz", "q": "지금 사과의 한계효용은 6, 가격은 3천 원이고, 귤의 한계효용은 4, 가격은 1천 원이에요. 만족을 늘리려면?", "options": ["귤을 더 사고 사과를 덜 사요", "사과를 더 사고 귤을 덜 사요", "지금 그대로가 가장 좋아요", "둘 다 사지 않아요"], "answer": 0, "explanation": "1천 원당 한계효용은 사과 6 ÷ 3 = 2, 귤 4 ÷ 1 = 4예요. 1원당 한계효용이 큰 귤을 늘리고 사과를 줄여야 만족이 커져요.", "lessonCheck": true},
  {"type": "quiz", "q": "한계효용이 줄어들고 있지만 아직 0보다 커요. 총효용은?", "options": ["계속 늘어요", "줄어들어요", "변하지 않아요", "0이 돼요"], "answer": 0, "explanation": "하나 더 소비할 때 만족이 조금이라도 늘면 총효용은 커져요. 늘어나는 폭이 작아질 뿐이에요."}
]'::jsonb || COALESCE(visuals,'[]'::jsonb)
WHERE id = 645 AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"title": "한계효용 쉽게 설명"}]'::jsonb;

-- 생산가능곡선 (810)
UPDATE public.words SET visuals = '[
  {"type": "text", "title": "생산가능곡선 쉽게 설명", "body": "가진 자원과 기술을 모두 써서 만들 수 있는 두 재화의 최대 조합을 이은 선이에요.\n자원이 희소해서 하나를 더 만들려면 다른 하나를 줄여야 하니 오른쪽 아래로 내려가요.\n한쪽을 늘릴수록 포기해야 하는 양(기회비용)이 커져서 바깥으로 불룩한 모양이에요."},
  {"type": "table", "title": "점의 위치가 뜻하는 것", "columns": ["위치", "의미", "예"], "rows": [["곡선 위", "자원을 모두 효율적으로 씀", "정상 가동"], ["곡선 안쪽", "자원을 다 못 씀", "높은 실업, 파업"], ["곡선 바깥", "지금 능력으로는 못 만듦", "기술 진보·자원 증가가 있어야 가능"]], "caption": "실업이 늘면 곡선이 움직이는 게 아니라 생산하는 점이 곡선 안쪽으로 들어가요."},
  {"type": "text", "title": "곡선이 바깥으로 움직일 때", "body": "인구가 늘거나 자본이 쌓이면 곡선 전체가 바깥으로 넓어져요.\n자동차 기술만 좋아지면 자동차 쪽 끝만 바깥으로 늘어나고, 자동차 1대의 기회비용은 줄어요."},
  {"type": "quiz", "q": "경기가 나빠져 실업자가 크게 늘었어요. 생산가능곡선에서는 어떻게 나타날까요?", "options": ["곡선은 그대로이고 생산하는 점이 곡선 안쪽으로 들어가요", "곡선 전체가 바깥으로 이동해요", "곡선 전체가 안쪽으로 이동해요", "생산하는 점이 곡선 바깥으로 나가요"], "answer": 0, "explanation": "실업은 있는 자원을 다 못 쓰는 상태예요. 만들 수 있는 능력인 곡선은 그대로이고 실제 생산이 곡선 안쪽에 머물러요.", "lessonCheck": true},
  {"type": "quiz", "q": "생산가능곡선이 바깥으로 불룩한(원점에 대해 오목한) 이유는?", "options": ["한 재화를 늘릴수록 기회비용이 커져서", "자원이 무한해서", "기회비용이 늘 일정해서", "두 재화가 보완재라서"], "answer": 0, "explanation": "처음에는 그 재화를 잘 만드는 자원부터 옮기지만, 갈수록 다른 재화를 더 잘 만드는 자원까지 옮겨야 해요. 그래서 포기하는 양이 점점 커져요."}
]'::jsonb || COALESCE(visuals,'[]'::jsonb)
WHERE id = 810 AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"title": "생산가능곡선 쉽게 설명"}]'::jsonb;

-- 무차별곡선 (803)
UPDATE public.words SET visuals = '[
  {"type": "text", "title": "무차별곡선 쉽게 설명", "body": "만족(효용)이 똑같은 상품 조합들을 이은 선이에요.\n빵 2개·우유 8개, 빵 4개·우유 4개, 빵 8개·우유 2개가 나한테 똑같이 좋다면 셋은 한 곡선 위에 있어요.\n원점에서 먼 곡선일수록 더 많이 가져서 만족이 커요."},
  {"type": "table", "title": "무차별곡선의 성질 4가지", "columns": ["성질", "이유"], "rows": [["오른쪽 아래로 내려감", "하나를 늘리면 다른 하나를 줄여야 만족이 같음"], ["원점에서 멀수록 효용이 큼", "많을수록 좋다는 가정"], ["서로 교차하지 않음", "교차하면 만족이 같다는 결론과 다르다는 결론이 부딪힘"], ["원점을 향해 볼록", "한계대체율이 줄어듦(골고루를 좋아함)"]]},
  {"type": "text", "title": "한계대체율", "body": "만족을 그대로 두면서 빵 1개를 더 얻으려고 내줄 수 있는 우유의 양이에요. 곡선 위 한 점의 접선 기울기 크기와 같아요.\n빵이 흔해질수록 빵 1개에 내줄 우유가 줄어들어요. 이 한계대체율 체감 때문에 곡선이 볼록해요."},
  {"type": "quiz", "q": "한 소비자의 같은 무차별곡선 위에 A(빵 2개·우유 6개)와 B(빵 3개·우유 4개)가 있어요. 옳은 것은?", "options": ["A와 B는 이 소비자에게 만족이 같아요", "B가 빵이 많으니 항상 더 좋아요", "A가 전체 개수가 많으니 항상 더 좋아요", "두 조합은 비교할 수 없어요"], "answer": 0, "explanation": "같은 무차별곡선 위의 점은 만족이 똑같아요. 그래서 차이가 없다는 뜻의 무차별이라는 이름이 붙었어요.", "lessonCheck": true},
  {"type": "quiz", "q": "일반적인 무차별곡선의 성질이 아닌 것은?", "options": ["두 곡선이 서로 교차해요", "오른쪽 아래로 내려가요", "원점에서 멀수록 효용이 커요", "원점을 향해 볼록해요"], "answer": 0, "explanation": "무차별곡선이 교차하면 많을수록 좋다는 가정과 모순이 생겨요. 그래서 서로 교차하지 않아요."}
]'::jsonb || COALESCE(visuals,'[]'::jsonb)
WHERE id = 803 AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"title": "무차별곡선 쉽게 설명"}]'::jsonb;

-- 수확체감의 법칙 (324)
UPDATE public.words SET visuals = '[
  {"type": "text", "title": "수확체감의 법칙 쉽게 설명", "body": "땅이나 공장처럼 당장 늘릴 수 없는 생산요소가 있을 때, 일하는 사람만 계속 늘리면 어느 순간부터 한 명 더해 늘어나는 생산량(한계생산)이 줄어드는 현상이에요.\n논은 그대로인데 사람만 늘면 한 사람이 맡을 땅이 줄어서예요."},
  {"type": "table", "title": "논농사로 보는 수확체감", "columns": ["일하는 사람", "한계생산", "총생산"], "rows": [["4명", "5가마", "14가마"], ["5명", "4가마", "18가마"], ["6명", "3가마", "21가마"], ["7명", "2가마", "23가마"], ["8명", "1가마", "24가마"], ["9명", "0가마", "24가마"], ["10명", "-1가마", "23가마"]], "caption": "5번째 사람부터 한계생산이 줄지만, 0보다 크면 총생산은 계속 늘어요."},
  {"type": "text", "title": "규모에 대한 수익과 헷갈리지 않기", "body": "수확체감은 고정된 요소가 있는 단기에, 노동 하나만 늘릴 때의 이야기예요.\n노동과 자본을 함께 2배로 늘리는 장기 이야기는 규모에 대한 수익이라고 따로 불러요."},
  {"type": "quiz", "q": "작은 식당의 주방 크기는 그대로인데 요리사를 계속 늘렸더니, 새 요리사가 더해 늘어나는 요리 수가 점점 줄었어요. 이 현상은?", "options": ["수확체감의 법칙", "규모의 경제", "규모에 대한 수익 체증", "범위의 경제"], "answer": 0, "explanation": "주방이라는 고정요소가 있는 상태에서 노동만 늘리니 한계생산이 줄었어요. 단기에 나타나는 수확체감이에요.", "lessonCheck": true},
  {"type": "quiz", "q": "수확체감의 법칙에 대한 설명으로 옳은 것은?", "options": ["고정된 생산요소가 있는 단기에 나타나요", "모든 생산요소를 함께 늘리는 장기에 나타나요", "한계생산이 줄면 총생산도 반드시 줄어요", "평균생산이 줄어드는 현상을 말해요"], "answer": 0, "explanation": "수확체감은 고정요소가 있는 단기에 가변요소만 늘릴 때 한계생산이 줄어드는 현상이에요. 한계생산이 0보다 크면 총생산은 여전히 늘어요."}
]'::jsonb || COALESCE(visuals,'[]'::jsonb)
WHERE id = 324 AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"title": "수확체감의 법칙 쉽게 설명"}]'::jsonb;

-- 규모의 경제 (94)
UPDATE public.words SET visuals = '[
  {"type": "text", "title": "규모의 경제 쉽게 설명", "body": "생산량을 늘릴수록 하나를 만드는 평균비용(장기평균비용)이 낮아지는 현상이에요.\n대형 공장, 반도체처럼 처음 설비에 큰돈이 드는 산업에서 잘 나타나요.\n많이 만들수록 개당 비용이 낮아져 큰 기업이 유리하고, 한 기업만 남는 자연독점이 생기기도 해요."},
  {"type": "table", "title": "규모의 경제와 비슷한 개념", "columns": ["개념", "뜻", "예"], "rows": [["규모의 경제", "많이 만들수록 장기평균비용이 줄어듦", "대형 공장"], ["범위의 경제", "여러 제품을 같이 만들면 따로 만들 때보다 쌈", "도축장의 고기·가죽"], ["수확체감", "단기에 노동만 늘리면 한계생산이 줄어듦", "좁은 주방의 요리사"]]},
  {"type": "text", "title": "규모에 대한 수익과의 관계", "body": "노동과 자본을 2배로 늘렸을 때 생산이 2배보다 많이 늘면 규모에 대한 수익 체증이에요. 이때 보통 장기평균비용이 줄어 규모의 경제가 나타나요.\n다만 규모에 대한 수익은 투입과 생산량을, 규모의 경제는 생산량과 비용을 보는 다른 개념이에요."},
  {"type": "quiz", "q": "한 회사가 공장을 크게 지어 생산량을 늘렸더니 제품 1개를 만드는 평균비용이 낮아졌어요. 이 현상은?", "options": ["규모의 경제", "범위의 경제", "수확체감의 법칙", "한계효용 체감"], "answer": 0, "explanation": "생산 규모가 커지면서 장기평균비용이 줄어드는 것이 규모의 경제예요. 여러 제품을 함께 만들어 비용이 줄면 범위의 경제예요.", "lessonCheck": true},
  {"type": "quiz", "q": "규모의 경제와 범위의 경제를 바르게 구분한 것은?", "options": ["규모의 경제는 많이 만들어서, 범위의 경제는 여러 가지를 같이 만들어서 비용이 줄어요", "둘은 같은 뜻이에요", "규모의 경제는 단기, 범위의 경제는 장기 개념이에요", "범위의 경제는 생산량이 늘수록 비용이 늘어나는 현상이에요"], "answer": 0, "explanation": "규모의 경제는 얼마나 많이 만드느냐, 범위의 경제는 몇 가지를 함께 만드느냐의 문제예요."}
]'::jsonb || COALESCE(visuals,'[]'::jsonb)
WHERE id = 94 AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"title": "규모의 경제 쉽게 설명"}]'::jsonb;

NOTIFY pgrst, 'reload schema';

